const raw = $input.first().json;
const body = raw.body || raw;

// Normaliser le nom d'événement (v1/v2)
const event = String(body.event || body.type || '').toLowerCase().replace(/_/g, '.');
const isMessageEvent = event === 'messages.upsert' || event.endsWith('messages.upsert');
if (!isMessageEvent && body.data?.key == null && !body.data?.messages) {
  return [{ json: { skip: true, reason: 'not_a_message_event', event: body.event } }];
}

// Evolution v2: data = message ; v1: data.messages[0]
let msg = null;
if (body.data?.messages?.[0]) {
  msg = body.data.messages[0];
} else if (body.data?.key) {
  msg = body.data;
} else if (body.key) {
  msg = body;
}

if (!msg) {
  return [{ json: { skip: true, reason: 'no_message_data', keys: Object.keys(body || {}) } }];
}

if (msg.key?.fromMe === true) {
  return [{ json: { skip: true, reason: 'from_me' } }];
}

const remoteJid = msg.key?.remoteJid || '';
// Ignorer groupes / status / newsletters
if (remoteJid.includes('@g.us') || remoteJid.includes('status@broadcast') || remoteJid.includes('@newsletter')) {
  return [{ json: { skip: true, reason: 'not_direct_chat', remoteJid } }];
}

const from = remoteJid
  .replace('@s.whatsapp.net', '')
  .replace('@c.us', '')
  .replace(/:\d+$/, '')
  .replace(/\D/g, '');

const m = msg.message || {};
const text = (
  m.conversation
  || m.extendedTextMessage?.text
  || m.imageMessage?.caption
  || m.videoMessage?.caption
  || m.buttonsResponseMessage?.selectedDisplayText
  || m.listResponseMessage?.title
  || m.templateButtonReplyMessage?.selectedDisplayText
  || ''
).trim();

if (!text) {
  return [{ json: { skip: true, reason: 'empty_text', messageType: msg.messageType } }];
}

const OWNER = '25779928864';
if (from !== OWNER) {
  return [{ json: { skip: true, reason: 'unauthorized', from } }];
}

return [{
  json: {
    skip: false,
    from,
    text,
    instanceName: body.instance || 'jarvis-principal',
    messageId: msg.key?.id || null
  }
}];

